import{uid,inBounds}from'./model.js';
import{newScene,prepareScene}from'./authoring-model.js';
import{addQuestFlag}from'./quest-model.js';
export const QUEST_PRESETS={supplyRun:{name:'Supply run',hint:'Accept the request, collect supplies from a cache, then hand them in for payment.'},courier:{name:'Courier job',hint:'Place a sender and recipient. Accept the job, deliver the message, then return.'},rescue:{name:'Rescue and reunion',hint:'Place the owner and lost Pokémon. Find it before collecting the reward.'},treasure:{name:'Treasure trail',hint:'Place two clues and the cache. Each discovery unlocks the next.'},switches:{name:'Three-switch puzzle',hint:'Place three switches and a reward. Each switch can only count once.'},patrol:{name:'Ranger patrol',hint:'Place three checkpoints and the ranger. Visit all three for a reward.'}};
// Detached drafts: choosing or cancelling a kit never allocates project save slots.
export function questPreset(project,kind){
 if(!Object.hasOwn(QUEST_PRESETS,kind))throw Error('Unknown quest template.');
 const kit={id:uid(),kind,name:QUEST_PRESETS[kind].name,flags:[],scenes:[]},say=text=>({type:'say',text}),flag=(name)=>{const q={id:uid(),name:kit.name+': '+name};kit.flags.push(q);return q.id;},set=flagId=>({type:'flag',flagId,value:true}),has=flagId=>({kind:'flag',flagId,value:true}),give=()=>({type:'item',operation:'give',itemId:4,quantity:2});
 const scene=(title,steps,{conditions=[],failText='',repeatSteps=[say('You have already done this.')] }={})=>{const n=newScene(project,0,0);n.title=title;n.runtime={...n.runtime,repeat:'once',conditions,failText,steps,repeatSteps};kit.scenes.push(n);return n;};
 if(kind==='supplyRun'){
  const accepted=flag('Request accepted'),collected=flag('Cache collected'),delivered=flag('Supplies delivered');
  scene('Supplies · requester',[{type:'choice',text:'Will you collect three POTIONs for us?',yes:[set(accepted),say('The supply cache is waiting. Bring the supplies to the recipient.')],no:[say('Come back if you change your mind.'),{type:'abort'}]}],{repeatSteps:[{type:'if',conditions:[has(delivered)],then:[say('The supplies arrived. Thank you for helping!')],else:[say('Collect the supplies and take them to the recipient.')]}]});
  scene('Supplies · cache',[{type:'item',operation:'give',itemId:13,quantity:3,notify:true},set(collected)],{conditions:[has(accepted)],failText:'These supplies are reserved. Speak to the requester first.',repeatSteps:[say('The supply cache is empty.')]});
  scene('Supplies · recipient',[{type:'choice',text:'Hand over three POTIONs for 500?',yes:[{type:'item',operation:'take',itemId:13,quantity:3},{type:'money',operation:'give',amount:500},set(delivered),say('These will help. Here is your payment!')],no:[say('Keep them safe until you are ready.'),{type:'abort'}]}],{conditions:[has(accepted),has(collected),{kind:'item',itemId:13,quantity:3}],failText:'Accept the request and bring three POTIONs before collecting payment.',repeatSteps:[say('Thank you. Your payment has already been collected.')]});
 }
 if(kind==='courier'){const accepted=flag('Job accepted'),delivered=flag('Message delivered');scene('Courier · sender',[{type:'choice',text:'Will you deliver a message for me?',yes:[set(accepted),say('Speak to the recipient. They are expecting you.')],no:[say('Let me know if you change your mind.'),{type:'abort'}]}],{repeatSteps:[{type:'if',conditions:[has(delivered)],then:[say('The message arrived. Thank you!')],else:[say('The recipient is still waiting for my message.')]}]});scene('Courier · recipient',[say('A message for me? Thank you.'),{type:'money',operation:'give',amount:300},set(delivered)],{conditions:[has(accepted)],failText:'I am expecting a message from a friend.',repeatSteps:[say('Please tell the sender it arrived safely.')]});}
 if(kind==='rescue'){const found=flag('Pokémon found');scene('Rescue · owner',[give(),say('You found my Pokémon! Thank you.')],{conditions:[has(found)],failText:'My Pokémon wandered off. Please help me find it.',repeatSteps:[say('We will be more careful next time.')]});scene('Rescue · lost Pokémon',[{type:'cry',species:25,wait:true},say('The lost Pokémon recognises the way home.'),set(found)],{repeatSteps:[say('It has returned to its owner.')]});}
 if(kind==='treasure'){const first=flag('First clue found'),second=flag('Second clue found');scene('Treasure · first clue',[say('A faded note: follow the water to the next marker.'),set(first)],{repeatSteps:[say('Follow the water to the next marker.')]});scene('Treasure · second clue',[say('Another note: the cache is beside the old path.'),set(second)],{conditions:[has(first)],failText:'The markings make no sense. There must be another clue.',repeatSteps:[say('Look beside the old path.')]});scene('Treasure · cache',[give(),say('The clues led you to the treasure!')],{conditions:[has(second)],failText:'It is locked. Find the clues first.',repeatSteps:[say('The cache is empty.')]});}
 if(['switches','patrol'].includes(kind)){const flags=Array.from({length:3},(_,i)=>flag((kind==='switches'?'Switch ':'Checkpoint ')+(i+1)));flags.forEach((id,i)=>{const n=scene((kind==='switches'?'Puzzle · switch ':'Patrol · checkpoint ')+(i+1),[{type:'sound',soundId:5},set(id),say(kind==='switches'?'The switch clicks into place.':'You checked this part of the route.')],{repeatSteps:[say(kind==='switches'?'This switch is already set.':'You already checked this location.')]});if(kind==='patrol')n.runtime.trigger='step';});scene(kind==='switches'?'Puzzle · reward':'Patrol · ranger',[give(),say(kind==='switches'?'All three switches are set. Well done!':'Every checkpoint is clear. Good work.')],{conditions:flags.map(has),failText:kind==='switches'?'Three switches must be set first.':'Check all three locations before returning.',repeatSteps:[say('Thanks again.')]});}
 const identify=steps=>steps.map(s=>{const a={id:uid(),...s};for(const key of ['yes','no','then','else'])if(a[key])a[key]=identify(a[key]);return a;});for(const n of kit.scenes){n.runtime.steps=identify(n.runtime.steps);n.runtime.repeatSteps=identify(n.runtime.repeatSteps);}return kit;
}
export function placeQuestPreset(project,kit,placements){
 if(!Object.hasOwn(QUEST_PRESETS,kit.kind)||placements.length!==kit.scenes.length)throw Error('Place every quest stage before saving.');
 const occupied=new Set();for(const [i,at]of placements.entries()){const m=project.maps.find(m=>m.id===at.mapId);if(!m||!Number.isInteger(at.x)||!Number.isInteger(at.y)||!inBounds(m,at.x,at.y))throw Error('Place each stage inside a map.');const key=at.mapId+':'+at.x+':'+at.y;if(occupied.has(key)||m.markers.some(n=>n.x===at.x&&n.y===at.y&&n.runtime))throw Error('Choose a separate tile for each quest stage.');occupied.add(key);if(m.markers.length+placements.filter(p=>p.mapId===m.id).length>512)throw Error('This map has too many markers.');}
 const next=(project.questFlags||[]).reduce((n,q)=>Math.max(n,q.slot+1),0);if(next+kit.flags.length+kit.scenes.length>1024)throw Error('Not enough project save slots remain for this quest.');
 if(kit.flags.some(q=>project.questFlags?.some(old=>old.id===q.id))||kit.scenes.some(n=>project.maps.some(m=>m.markers.some(old=>old.id===n.id))))throw Error('This quest has already been placed.');
 for(const q of kit.flags)addQuestFlag(project,q.name,q.id);
 return kit.scenes.map((draft,i)=>{const n=structuredClone(draft),at=placements[i],m=project.maps.find(m=>m.id===at.mapId);n.x=at.x;n.y=at.y;prepareScene(project,n);m.markers.push(n);return{mapId:m.id,eventId:n.id};});
}
